describe('Sidebar Collapse and Expand Functionality', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.get('[data-testid="sidebar"]').should('be.visible');
  });

  it('should expand sidebar when collapse button is clicked on collapsed state', () => {
    // Verify sidebar is initially expanded
    cy.get('[data-testid="sidebar"]').should('have.class', 'expanded');
    cy.get('[data-testid="sidebar-content"]').should('be.visible');
    cy.get('[data-testid="sidebar-toggle-btn"]').should('have.attr', 'aria-expanded', 'true');

    // Click collapse button
    cy.get('[data-testid="sidebar-toggle-btn"]').click();

    // Verify sidebar is collapsed
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');
    cy.get('[data-testid="sidebar-content"]').should('not.be.visible');
    cy.get('[data-testid="sidebar-toggle-btn"]').should('have.attr', 'aria-expanded', 'false');

    // Click expand button
    cy.get('[data-testid="sidebar-toggle-btn"]').click();

    // Verify sidebar is expanded again
    cy.get('[data-testid="sidebar"]').should('have.class', 'expanded');
    cy.get('[data-testid="sidebar-content"]').should('be.visible');
    cy.get('[data-testid="sidebar-toggle-btn"]').should('have.attr', 'aria-expanded', 'true');
  });

  it('should persist sidebar state across page navigation', () => {
    // Collapse the sidebar
    cy.get('[data-testid="sidebar-toggle-btn"]').click();
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');

    // Navigate to another page
    cy.get('[data-testid="nav-link-about"]').click();
    cy.url().should('include', '/about');

    // Verify sidebar remains collapsed
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');
    cy.get('[data-testid="sidebar-content"]').should('not.be.visible');

    // Navigate back
    cy.get('[data-testid="nav-link-home"]').click();
    cy.url().should('include', '/');

    // Verify sidebar is still collapsed
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');
  });

  it('should handle rapid toggle clicks without breaking state', () => {
    const toggleBtn = cy.get('[data-testid="sidebar-toggle-btn"]');

    // Perform rapid clicks
    toggleBtn.click();
    toggleBtn.click();
    toggleBtn.click();

    // Verify sidebar is in correct state (should be collapsed after 3 clicks)
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');
    cy.get('[data-testid="sidebar-content"]').should('not.be.visible');

    // One more click to expand
    toggleBtn.click();
    cy.get('[data-testid="sidebar"]').should('have.class', 'expanded');
    cy.get('[data-testid="sidebar-content"]').should('be.visible');
  });

  it('should update sidebar width smoothly during collapse animation', () => {
    const sidebar = cy.get('[data-testid="sidebar"]');

    // Get initial width
    sidebar.invoke('width').then((initialWidth) => {
      expect(initialWidth).to.be.greaterThan(200);

      // Click to collapse
      cy.get('[data-testid="sidebar-toggle-btn"]').click();

      // Wait for animation to complete
      cy.wait(500);

      // Verify width has decreased
      sidebar.invoke('width').then((collapsedWidth) => {
        expect(collapsedWidth).to.be.lessThan(initialWidth);
        expect(collapsedWidth).to.equal(60);
      });
    });
  });

  it('should maintain sidebar functionality when toggled with keyboard navigation', () => {
    // Focus on toggle button
    cy.get('[data-testid="sidebar-toggle-btn"]').focus();

    // Verify button is focused
    cy.get('[data-testid="sidebar-toggle-btn"]').should('have.focus');

    // Press Enter to toggle
    cy.get('[data-testid="sidebar-toggle-btn"]').type('{enter}');

    // Verify sidebar collapsed
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');

    // Press Space to toggle back
    cy.get('[data-testid="sidebar-toggle-btn"]').type(' ');

    // Verify sidebar expanded
    cy.get('[data-testid="sidebar"]').should('have.class', 'expanded');
  });

  it('should handle sidebar toggle on mobile viewport', () => {
    // Set mobile viewport
    cy.viewport('iphone-x');

    // Verify sidebar is initially visible
    cy.get('[data-testid="sidebar"]').should('be.visible');

    // Click toggle button
    cy.get('[data-testid="sidebar-toggle-btn"]').click();

    // Verify sidebar collapses on mobile
    cy.get('[data-testid="sidebar"]').should('have.class', 'collapsed');

    // Verify toggle button is still accessible
    cy.get('[data-testid="sidebar-toggle-btn"]').should('be.visible');
    cy.get('[data-testid="sidebar-toggle-btn"]').click();

    // Verify sidebar expands
    cy.get('[data-testid="sidebar"]').should('have.class', 'expanded');
  });
});
